        "NO_DEDUP_REQUESTED": str(no_dedup_requested).lower(),
        "RUN_ID": run_id,
        "POSITIONAL_KIND": positional_kind,
        "POSITIONAL_VALUE": positional_value,
    }

    if output_path and not _write_output(output_path, output_fields):
